def check(name):
    if len(name) < 3:
        return "too_short"
    if len(name) > 12:
        return "too_long"
    first = name[0]
    if not (first.isalpha() or first == "_"):
        return "bad_start"
    for ch in name:
        if not (ch.isalpha() or ch.isdigit() or ch == "_"):
            return "bad_char"
    return "valid"

def main():
    n = int(input())
    valid_count = 0
    for i in range(n):
        name = input()
        verdict = check(name)
        if verdict == "valid":
            valid_count = valid_count + 1
            print(f"{name}: VALID")
        else:
            print(f"{name}: INVALID ({verdict})")
    print(f"{valid_count} of {n} names are valid")

main()

