def memo(func):
    cache = {}

    def wrapper(k):
        if k not in cache:
            cache[k] = func(k)
        return cache[k]

    return wrapper


@memo
def growth(k):
    if k <= 2:
        return 1
    return growth(k - 1) + growth(k - 2)


