class FlakyError(Exception):
    pass


def retry(limit):
    def deco(func):
        def wrapper():
            for attempt in range(1, limit + 1):
                print(f"attempt {attempt}")
                try:
                    func(attempt)
                    print(f"success on attempt {attempt}")
                    return "OK"
                except FlakyError:
                    print("failed")
            print("job aborted")
            return None

        return wrapper

    return deco


